import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { useOffersMyListQuery } from 'entities/Offer';
import { getUrlParamsForApi } from 'features/Filters';
import { PageTitle } from 'shared/ui';
import { OfferList } from 'widgets/OfferList';

interface IMyOffersProps extends HTMLAttributes<HTMLDivElement> {}

export const MyOffers: FC<IMyOffersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const [searchParams] = useSearchParams();
	const { data, isFetching } = useOffersMyListQuery(getUrlParamsForApi(searchParams));

	return (
		<>
			<PageTitle type="filled">{t('My Offers')}</PageTitle>
			<OfferList data={data} isMyOffers={true} {...props} isFetching={isFetching} />
		</>
	);
};

export default MyOffers;
