import { FC, Fragment, HTMLAttributes } from 'react';

import { Pagination as AntdPagination, type PaginationProps } from 'antd';
import cn from 'classnames';

import { useSearchParamsWithHash } from 'shared/hooks';

import { CONFIG } from '../../config/config';
import { EPagination, EPaginationParams } from '../../model/types';

import styles from './Pagination.module.scss';

interface IPaginationProps extends HTMLAttributes<HTMLDivElement> {
	count?: number;
	minCount?: number;
}

export const Pagination: FC<IPaginationProps> = ({ className, count = 1, minCount = EPagination.MIN, ...props }) => {
	const [searchParams, setSearchParams] = useSearchParamsWithHash();

	const offset = searchParams.get(EPaginationParams.OFFSET);
	const offsetIndex = isNaN(Number(offset)) ? 0 : Number(offset);

	const limit = searchParams.get(EPaginationParams.LIMIT);
	const perPage = isNaN(Number(limit)) || Number(limit) < 1 ? CONFIG.PER_PAGE : Number(limit);

	const onPaginate: PaginationProps['onChange'] = (page: number, pageSize: number) => {
		const newPerPage = pageSize || CONFIG.PER_PAGE;
		const newPageNumber = page || 1;
		const newOffsetIndex = newPerPage * (newPageNumber - 1);

		searchParams.set(EPaginationParams.LIMIT, newPerPage.toString());
		searchParams.set(EPaginationParams.OFFSET, newOffsetIndex.toString());

		setSearchParams(searchParams);
	};

	return (
		<Fragment>
			{count > minCount && (
				<AntdPagination
					{...props}
					className={cn(className, styles.pagination)}
					showQuickJumper
					hideOnSinglePage
					total={count}
					pageSize={perPage}
					current={Math.floor(offsetIndex / perPage) + 1}
					onChange={onPaginate}
					showSizeChanger={false}
					size={'default'}
					pageSizeOptions={CONFIG.PER_PAGE_OPTIONS}
				/>
			)}
		</Fragment>
	);
};
