import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import cn from 'classnames';

import { OffersListApiResponse } from 'entities/Offer';
import { MainFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { Sort } from 'features/Sort';
import { ListTopbar, NoResults, OverlayLoader } from 'shared/ui';

import { SORT_ITEMS } from '../../consts/sortItems';

import styles from './OfferList.module.scss';

const initialOfferList = {
	count: 0,
	next: null,
	previous: null,
	results: [],
};

interface IOfferListProps extends HTMLAttributes<HTMLDivElement> {
	data?: OffersListApiResponse;
	isMyOffers?: boolean;
	isFetching?: boolean;
}

export const OfferList: FC<IOfferListProps> = ({ className, data = initialOfferList, isFetching, ...props }) => {
	const { t } = useTranslation();
	const hasData = data.results?.length && data.results?.length > 0;
	const { count = 0 } = data;

	return (
		<div {...props} className={cn(className, styles.offerList)}>
			<MainFilters />

			{!hasData && (
				<div>
					{isFetching && <OverlayLoader />}
					<NoResults />
				</div>
			)}

			{!!hasData && count > 0 && (
				<>
					<ListTopbar
						leftComponent={<Sort sortItems={SORT_ITEMS} />}
						rightText={t('Active brands')}
						rightData={data?.count}
					/>

					<Pagination count={count} />
				</>
			)}
		</div>
	);
};
