import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';

import { Checkbox, Select } from 'antd';
import cn from 'classnames';

import { SourcesRelationsStatusEnum } from 'entities/Offer';
import { EFilters } from 'features/Filters/model/enums';
import { CAPS_OPTIONS, FILTER_STATUS_OPTIONS } from 'shared/consts';
import { EMainRoutes } from 'shared/typings';
import { InfoTooltip } from 'shared/ui';

import { OPTIONS_MAX_HEIGHT_EXTENDED, OPTIONS_MAX_HEIGHT_MAIN } from '../../consts';
import { useOffersSelect } from '../../hooks/useOffersSelect';
import { useStateFilters } from '../../hooks/useStateFilters';
import { ExtendedFiltersSection } from '../ExtendedFiltersSection/ExtendedFiltersSection';
import { ExtendedFiltersWrapper } from '../ExtendedFiltersWrapper/ExtendedFiltersWrapper';

import styles from './ExtendedFilters.module.scss';

interface IExtendedFiltersProps extends HTMLAttributes<HTMLDivElement> {
	appliedFiltersCount: number;
}

export const ExtendedFilters: FC<IExtendedFiltersProps> = ({ className, appliedFiltersCount, ...props }) => {
	const { t } = useTranslation();
	const { applyFilters, getALLFilterValues, getFilterValue, clearFilters, onFilterChange, setInitFiltersFilters } =
		useStateFilters();
	const { isFetching, isLoading, offersOptions, setSearchValue } = useOffersSelect();
	const { pathname } = useLocation();
	const isMyOffers = pathname === `/${EMainRoutes.MY_OFFERS}`;

	return (
		<ExtendedFiltersWrapper
			applyFilters={applyFilters}
			appliedFiltersCount={appliedFiltersCount}
			clearFilters={clearFilters}
			onOpen={setInitFiltersFilters}>
			<div {...props} className={cn(className, styles.extendedFilters)}>
				<div className={styles.extendedFilters__col}>
					<ExtendedFiltersSection title={t('Base filters')}>
						<Select
							className={styles.select}
							onChange={(value) => onFilterChange(EFilters.CAP, value)}
							value={getALLFilterValues(EFilters.CAP)}
							options={CAPS_OPTIONS}
							placeholder={t('Cap')}
							size="large"
							allowClear
						/>
					</ExtendedFiltersSection>

					<ExtendedFiltersSection title={t('Apps and Tracking')}>
						<Checkbox
							checked={!!getFilterValue(EFilters.MMP_LINK)}
							onChange={(e) => onFilterChange(EFilters.MMP_LINK, e.target.checked ? true : null)}>
							<span className={styles.extendedFilters__tooltip}>
								{t('MMP Link')}
								<InfoTooltip text={t('Mmp link description')} />
							</span>
						</Checkbox>
					</ExtendedFiltersSection>
				</div>

				<div className={styles.extendedFilters__col}>
					<ExtendedFiltersSection title={t('Offers')}>
						<Select
							mode="multiple"
							value={getALLFilterValues(EFilters.OFFER)}
							options={offersOptions}
							onChange={(value) => {
								setSearchValue('');
								onFilterChange(EFilters.OFFER, Array.isArray(value) ? value : [value]);
							}}
							onSearch={setSearchValue}
							showSearch
							filterOption={false}
							optionFilterProp="label"
							allowClear
							disabled={isLoading}
							listHeight={OPTIONS_MAX_HEIGHT_MAIN}
							loading={isLoading || isFetching}
							placeholder={t('Offer name')}
							size="large"
						/>
					</ExtendedFiltersSection>
				</div>

				<div className={styles.extendedFilters__col}>
					<ExtendedFiltersSection title={t('Status')}>
						<Select
							className={styles.select}
							onChange={(value) => onFilterChange(EFilters.STATUS, value)}
							value={getALLFilterValues(EFilters.STATUS)}
							options={FILTER_STATUS_OPTIONS.filter(
								(item) => !isMyOffers || item.value !== SourcesRelationsStatusEnum.Rejected,
							)}
							placeholder={t('Status')}
							size="large"
							mode="multiple"
							listHeight={OPTIONS_MAX_HEIGHT_EXTENDED}
							allowClear
						/>
					</ExtendedFiltersSection>
				</div>
			</div>
		</ExtendedFiltersWrapper>
	);
};
